package com.furrynylos;

import org.junit.Assert;
import org.junit.Test;

public class BloodMoonRoomEndTest
{
	private static boolean matches(String message)
	{
		return message != null && BloodMoonPlugin.ROOM_END_MESSAGE.matcher(message).matches();
	}

	@Test
	public void matchesEntryMode()
	{
		Assert.assertTrue(matches("Wave 'The Nylocas' (Entry Mode) complete!"));
	}

	@Test
	public void matchesNormalMode()
	{
		Assert.assertTrue(matches("Wave 'The Nylocas' (Normal Mode) complete!"));
	}

	@Test
	public void matchesHardMode()
	{
		Assert.assertTrue(matches("Wave 'The Nylocas' (Hard Mode) complete!"));
	}

	@Test
	public void matchesStoryMode()
	{
		Assert.assertTrue(matches("Wave 'The Nylocas' (Story Mode) complete!"));
	}

	@Test
	public void rejectsHealthReplenishMessage()
	{
		Assert.assertFalse(matches("You feel refreshed as your health is replenished."));
	}

	@Test
	public void rejectsWrongRoom()
	{
		Assert.assertFalse(matches("Wave 'The Maiden' (Hard Mode) complete!"));
	}

	@Test
	public void rejectsDoubleQuotes()
	{
		Assert.assertFalse(matches("Wave \"The Nylocas\" (Hard Mode) complete!"));
	}

	@Test
	public void rejectsTrailingText()
	{
		Assert.assertFalse(matches("Wave 'The Nylocas' (Hard Mode) complete! extra"));
	}
}

