package com.furrynylos;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class BloodMoonOverlay extends OverlayPanel
{
	private final BloodMoonPlugin plugin;
	private final BloodMoonConfig config;

	@Inject
	private BloodMoonOverlay(BloodMoonPlugin plugin, BloodMoonConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || !plugin.isInRoom())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Furry Nyloer")
			.color(Color.RED)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("This run:")
			.right(plugin.getRunTicksSaved() + " ticks")
			.build());

		if (config.showLifetime())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Lifetime:")
				.right(plugin.getLifetimeTicksSaved() + " ticks")
				.build());
		}

		return super.render(graphics);
	}
}

package com.furrynylos;

import com.google.inject.Provides;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Named;
import lombok.Getter;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.apache.commons.lang3.ArrayUtils;

@PluginDescriptor(
	name = "Furry Nyloer",
	description = "Counts ticks saved by the Blood moon armour set effect in the Nylocas room",
	tags = {"tob", "nylo", "nylocas", "blood moon"}
)
public class BloodMoonPlugin extends Plugin
{
	private static final int NYLOCAS_REGION_ID = 13122;
	private static final int[] NYLOCAS_PILLAR_IDS = {
		NpcID.TOB_NYLOCAS_SUPPORT,
		NpcID.TOB_NYLOCAS_SUPPORT_STORY,
		NpcID.TOB_NYLOCAS_SUPPORT_HARD,
	};
	private static final int SAVED_TICK_SPOTANIM = SpotanimID.SPECIAL_DUAL_MACUAHUITL_SPOTANIM;
	static final Pattern ROOM_END_MESSAGE = Pattern.compile(
		"Wave 'The Nylocas' \\(.*\\) complete!"
	);

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private BloodMoonConfig config;

	@Inject
	private BloodMoonOverlay overlay;

	@Inject
	@Named("developerMode")
	private boolean developerMode;

	private boolean inRegion;
	private boolean wasInRegion;
	private int lastProcCycle = -1;

	@Getter
	private int runTicksSaved;

	@Getter
	private int lifetimeTicksSaved;

	@Provides
	BloodMoonConfig provideConfig(ConfigManager configManager, @Named("developerMode") boolean developerMode)
	{
		if (developerMode)
		{
			return configManager.getConfig(BloodMoonDevConfig.class);
		}
		return configManager.getConfig(BloodMoonConfig.class);
	}

	@Override
	protected void startUp()
	{
		lifetimeTicksSaved = config.lifetimeTicksSaved();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		resetRun();
		inRegion = false;
		wasInRegion = false;
	}

	public boolean isInRoom()
	{
		return inRegion || (developerMode && config.testMode());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			resetRun();
			inRegion = false;
			wasInRegion = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		inRegion = ArrayUtils.contains(client.getTopLevelWorldView().getMapRegions(), NYLOCAS_REGION_ID);
		if (inRegion && !wasInRegion)
		{
			resetRun();
		}
		wasInRegion = inRegion;

		if (!isInRoom())
		{
			return;
		}

		// the proc restarts the spotanim even if it's already playing, so compare
		// start cycles instead of just checking presence to catch back-to-back procs
		int procCycle = findProcStartCycle();
		if (procCycle != -1 && procCycle != lastProcCycle)
		{
			runTicksSaved++;
			// don't let test mode procs inflate the lifetime total
			if (inRegion)
			{
				lifetimeTicksSaved++;
				configManager.setConfiguration(BloodMoonConfig.GROUP, BloodMoonConfig.LIFETIME_KEY, lifetimeTicksSaved);
			}
		}
		lastProcCycle = procCycle;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		// pillars spawning means the round just started, even if we never left the region
		if (inRegion && ArrayUtils.contains(NYLOCAS_PILLAR_IDS, event.getNpc().getId()))
		{
			resetRun();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!inRegion || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String message = event.getMessage();
		if (message == null || !ROOM_END_MESSAGE.matcher(message).matches())
		{
			return;
		}

		String summary = new ChatMessageBuilder()
			.append("Blood moon set saved ")
			.append(ChatColorType.HIGHLIGHT)
			.append(runTicksSaved + " tick" + (runTicksSaved == 1 ? "" : "s"))
			.append(ChatColorType.NORMAL)
			.append(String.format(" (%.1fs) this run, ", runTicksSaved * 0.6))
			.append(ChatColorType.HIGHLIGHT)
			.append(Integer.toString(lifetimeTicksSaved))
			.append(ChatColorType.NORMAL)
			.append(" lifetime.")
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(summary)
			.build());
	}

	private int findProcStartCycle()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return -1;
		}
		for (ActorSpotAnim anim : local.getSpotAnims())
		{
			if (anim.getId() == SAVED_TICK_SPOTANIM)
			{
				return anim.getStartCycle();
			}
		}
		return -1;
	}

	private void resetRun()
	{
		runTicksSaved = 0;
		lastProcCycle = -1;
	}
}

package com.furrynylos;

import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

// swapped in for BloodMoonConfig when the client runs with --developer-mode
@ConfigGroup(BloodMoonConfig.GROUP)
public interface BloodMoonDevConfig extends BloodMoonConfig
{
	@ConfigItem(
		position = 2,
		keyName = TEST_MODE_KEY,
		name = "Test mode",
		description = "Show the overlay and count set procs everywhere, not just the Nylocas room."
	)
	@Override
	default boolean testMode()
	{
		return false;
	}
}

package com.furrynylos;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BloodMoonConfig.GROUP)
public interface BloodMoonConfig extends Config
{
	String GROUP = "furrynyloer";
	String LIFETIME_KEY = "lifetimeTicksSaved";
	String TEST_MODE_KEY = "testMode";

	@ConfigItem(
		position = 0,
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show the ticks-saved overlay while in the Nylocas room."
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "showLifetime",
		name = "Show lifetime total",
		description = "Show the lifetime ticks-saved total in the overlay."
	)
	default boolean showLifetime()
	{
		return true;
	}

	// hidden, persisted across sessions
	@ConfigItem(
		keyName = LIFETIME_KEY,
		name = "",
		description = "",
		hidden = true
	)
	default int lifetimeTicksSaved()
	{
		return 0;
	}

	// BloodMoonDevConfig unhides this in developer mode
	@ConfigItem(
		keyName = TEST_MODE_KEY,
		name = "",
		description = "",
		hidden = true
	)
	default boolean testMode()
	{
		return false;
	}
}
